import {drawStreetDetails} from './city-details.mjs?v=1.1.0';
import {WORLD,BUILDINGS,TARGET,TOKENS,SPAWN} from './heist-core.mjs?v=1.1.0';
const token=id=>TOKENS.find(t=>t.id===id);
function box(c,x,y,w,h,r=4){c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
function label(c,text,x,y,size=12,color='#d9d7bc'){c.fillStyle=color;c.font=`700 ${size}px system-ui,sans-serif`;c.textAlign='center';c.fillText(text,x,y);}
function tree(c,x,y,r=18){c.fillStyle='#152d2d66';c.beginPath();c.ellipse(x+9,y+12,r,r*.75,0,0,Math.PI*2);c.fill();c.fillStyle='#496451';c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();c.fillStyle='#6e8058';c.beginPath();c.arc(x-5,y-5,r*.65,0,Math.PI*2);c.fill();}
export function makeCity(){const canvas=document.createElement('canvas');canvas.width=WORLD.width;canvas.height=WORLD.height;const c=canvas.getContext('2d');c.fillStyle='#43564e';c.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<canvas.height;y+=32)for(let x=0;x<canvas.width;x+=32){c.fillStyle=(x+y)%64?'#54634d18':'#1b363918';c.fillRect(x,y,30,30);}
 for(const x of WORLD.roadX){c.fillStyle='#acaa8b';c.fillRect(x-77,0,154,WORLD.height);c.fillStyle='#344449';c.fillRect(x-54,0,108,WORLD.height);c.strokeStyle='#d9cc973a';c.lineWidth=3;c.setLineDash([15,20]);c.beginPath();c.moveTo(x,0);c.lineTo(x,WORLD.height);c.stroke();c.setLineDash([]);c.fillStyle='#7d8f7e';c.fillRect(x-61,0,5,WORLD.height);}
 for(const y of WORLD.roadY){c.fillStyle='#b5ad8b';c.fillRect(0,y-77,WORLD.width,154);c.fillStyle='#35464b';c.fillRect(0,y-54,WORLD.width,108);c.strokeStyle='#e2ce923b';c.lineWidth=3;c.setLineDash([15,20]);c.beginPath();c.moveTo(0,y);c.lineTo(WORLD.width,y);c.stroke();c.setLineDash([]);}
 for(const x of WORLD.roadX)for(const y of WORLD.roadY){c.fillStyle='#35464b';c.fillRect(x-54,y-54,108,108);c.fillStyle='#d5c8a7';for(let i=-40;i<=40;i+=16){c.fillRect(x+i,y-73,8,25);c.fillRect(x+i,y+49,8,25);c.fillRect(x-73,y+i,25,8);c.fillRect(x+49,y+i,25,8);}c.fillStyle='#172e30';box(c,x-77,y-84,6,20,2);box(c,x+71,y+64,6,20,2);c.fillStyle='#b2b976';c.beginPath();c.arc(x-74,y-77,2,0,7);c.fill();}
 for(const [i,b]of BUILDINGS.entries()){c.fillStyle='#15262b66';box(c,b.x+15,b.y+18,b.w,b.h,5);c.fillStyle='#293d3f';box(c,b.x-7,b.y-7,b.w+14,b.h+14,4);c.fillStyle=b.color;box(c,b.x,b.y,b.w,b.h,4);c.strokeStyle='#d6c5a15c';c.lineWidth=3;c.strokeRect(b.x+9,b.y+9,b.w-18,b.h-18);c.fillStyle='#2c434580';box(c,b.x+20,b.y+20,44,28,3);c.strokeStyle='#b3b8a069';for(let k=0;k<4;k++){c.beginPath();c.moveTo(b.x+25,b.y+24+k*6);c.lineTo(b.x+58,b.y+24+k*6);c.stroke();}c.fillStyle='#c6c5aa';box(c,b.x+b.w-51,b.y+20,25,32,3);c.fillStyle='#485c5b';box(c,b.x+b.w-47,b.y+24,17,24,1);if(b.w>200){c.fillStyle='#d8d4ae55';box(c,b.x+85,b.y+38,70,35,3);c.fillStyle='#7e8d7a';box(c,b.x+89,b.y+42,62,27,2);}c.fillStyle='#233e40';box(c,b.x+12,b.y+b.h-47,b.w-24,31,3);label(c,b.name,b.x+b.w/2,b.y+b.h-27,Math.min(13,b.w/b.name.length*1.65));c.fillStyle=i%2?'#e8c174':'#b7c79a';c.fillRect(b.x+b.w/2-16,b.y+b.h-5,32,10);for(let k=0;k<Math.floor(b.w/55);k++){c.fillStyle='#152e35';c.fillRect(b.x+22+k*50,b.y+89,27,19);c.fillStyle='#b5c3a168';c.fillRect(b.x+25+k*50,b.y+92,21,4);}tree(c,b.x-23,b.y+b.h-9,14);if(i%3===0)tree(c,b.x+b.w+24,b.y+65,21);}
 label(c,'RUA DAS OFICINAS',1100,713,16,'#d2c59e');label(c,'AVENIDA CENTRAL',1100,1174,16,'#d2c59e');label(c,'AVENIDA NORTE',1110,253,16,'#d2c59e');for(const y of [465,925]){c.save();c.translate(1344,y);c.rotate(-Math.PI/2);label(c,'RUA DO CINEMA',0,0,13,'#aeb99d');c.restore();}
 c.fillStyle='#d6c49b';for(let x=1425;x<1660;x+=74){c.fillRect(x,768,2,52);c.fillRect(x,818,70,2);}label(c,'ESTACIONAMENTO',1580,840,10,'#ddd3ad');c.fillStyle='#d2c18a';box(c,450,868,230,49,4);label(c,'SEGURANÇA ABSOLUTA*',565,887,14,'#253b3d');label(c,'*CONSULTE O ANDERSON',565,903,9,'#3a4d44');tree(c,1255,790,18);tree(c,1769,790,17);return canvas;}
export function carSprite(c,x,y,angle,color='#67a5b2',police=false,time=0){c.save();c.translate(x,y);c.rotate(angle);c.fillStyle='#0a202977';box(c,-29,-10,68,38,10);c.fillStyle='#101f26';for(const wx of [-21,18])for(const wy of [-19,14])box(c,wx-7,wy,14,7,2);c.fillStyle=color;box(c,-33,-17,66,34,10);c.strokeStyle='#1d3439';c.lineWidth=2;c.stroke();c.fillStyle='#d4d5b1';c.fillRect(26,-12,4,7);c.fillRect(26,5,4,7);c.fillStyle='#964c3f';c.fillRect(-32,-12,3,7);c.fillRect(-32,5,3,7);c.fillStyle='#243d49';c.beginPath();c.moveTo(8,-13);c.lineTo(21,-9);c.lineTo(21,9);c.lineTo(8,13);c.closePath();c.fill();c.fillStyle='#718f94';c.fillRect(9,-10,3,20);c.fillStyle='#2d4750';box(c,-22,-11,10,22,2);c.fillStyle=police?'#d7dac5':'#87b6bf';box(c,-10,-12,16,24,3);if(police){c.fillStyle='#d0d7c7';c.fillRect(-5,-16,7,32);c.fillStyle=Math.floor(time*3)%2?'#ed6f55':'#719fd8';c.fillRect(-4,-13,6,26);c.globalAlpha=.12;c.fillStyle='#d86c58';c.beginPath();c.arc(0,-19,40,0,7);c.fill();c.fillStyle='#6ea3e3';c.beginPath();c.arc(0,19,40,0,7);c.fill();}c.restore();}
export function personSprite(c,x,y,angle,time=0,color='#d8a25d',officer=false){c.save();c.translate(x,y);c.rotate(angle);c.fillStyle='#071f2866';c.beginPath();c.ellipse(4,4,10,7,0,0,7);c.fill();const stride=Math.sin(time*14)*3;c.fillStyle='#182d37';box(c,-11,-7+stride,11,5,2);box(c,-11,3-stride,11,5,2);c.fillStyle=color;box(c,-5,-9,14,18,5);c.fillStyle='#b68c66';box(c,1,-12,8,4,2);box(c,1,8,8,4,2);c.fillStyle=officer?'#334f68':'#3a3a35';c.beginPath();c.arc(6,0,7,0,7);c.fill();c.fillStyle=officer?'#506c7b':'#bd8856';c.beginPath();c.arc(7,-1,5,0,7);c.fill();c.fillStyle=officer?'#304d67':'#e1b16b';box(c,4,-7,9,7,3);c.fillStyle='#172b32';c.fillRect(11,-5,4,7);c.restore();}
export function drawCity(canvas,city,s,camera,prefs={}){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}const c=canvas.getContext('2d'),scale=rect.width/camera.w;c.setTransform(dpr,0,0,dpr,0,0);c.fillStyle='#182d33';c.fillRect(0,0,rect.width,rect.height);c.scale(scale,scale);c.translate(-camera.x,-camera.y);c.drawImage(city,0,0);const time=s.elapsed;drawStreetDetails(c,prefs.reduceMotion?0:time);
 const parked=[[590,205,0,'#b98466'],[770,505,Math.PI/2,'#b56858'],[1140,1250,0,'#9daf8a'],[1950,500,-Math.PI/2,'#b6ad87'],[570,790,0,'#b7b6a4']];for(const p of parked)carSprite(c,...p);
 if(!prefs.reduceMotion){carSprite(c,(time*54+120)%2300-50,296,0,'#bac0b3',true,time);carSprite(c,866,(time*38+250)%1600-50,Math.PI/2,'#bd966c');}
 const npcs=[[565,665,0,'#a694b8'],[1060,1090,0,'#b98675'],[1950,980,Math.PI/2,'#7eaa9f'],[245,520,Math.PI/2,'#adb27b']];for(const p of npcs){const amount=prefs.reduceMotion?0:Math.sin(time*.4+p[0])*48;personSprite(c,p[0]+Math.cos(p[2])*amount,p[1]+Math.sin(p[2])*amount,p[2],time,p[3]);}
 if(s.path?.length&&s.phase==='foot'){c.strokeStyle='#ecd49370';c.lineWidth=2;c.setLineDash([5,8]);c.beginPath();c.moveTo(s.actor.x,s.actor.y);for(const p of s.path)c.lineTo(p.x,p.y);c.stroke();c.setLineDash([]);}
 const car=s.phase==='drive'||s.phase==='finish'?s.car:TARGET;carSprite(c,car.x,car.y,car.angle,TARGET.color);if(s.discovered&&s.phase==='foot'){c.fillStyle='#f0cb75';c.beginPath();c.moveTo(TARGET.x,TARGET.y-44);c.lineTo(TARGET.x-7,TARGET.y-57);c.lineTo(TARGET.x+7,TARGET.y-57);c.fill();c.fillStyle='#102c32';box(c,TARGET.x-53,TARGET.y-89,106,27,4);label(c,'FORD KA',TARGET.x,TARGET.y-71,14,'#f1d18d');}
 if(['intro','foot'].includes(s.phase)){c.strokeStyle='#f1d18b';c.lineWidth=2;c.beginPath();c.ellipse(s.actor.x,s.actor.y,18,13,0,0,7);c.stroke();personSprite(c,s.actor.x,s.actor.y,s.actor.angle,s.path.length||s.walking?time:0);}
 if(s.phase==='caught'||s.phase==='gameover'){const t=Math.min(1,s.phaseTime/2.2),policeX=camera.x+camera.w+120+(TARGET.x+95-(camera.x+camera.w+120))*(1-Math.pow(1-t,3));carSprite(c,policeX,TARGET.y-22,Math.PI,'#bac6c0',true,prefs.reduceMotion?0:time);if(t>.65){const p=Math.min(1,(t-.65)/.35);personSprite(c,TARGET.x+90-p*62,TARGET.y-48-p*10,Math.PI,time,'#3a526c',true);personSprite(c,TARGET.x-45,TARGET.y-37,0,0);}}
 c.setTransform(dpr,0,0,dpr,0,0);const gradient=c.createRadialGradient(rect.width/2,rect.height/2,rect.width*.2,rect.width/2,rect.height/2,rect.width*.75);gradient.addColorStop(0,'#071a1d00');gradient.addColorStop(1,'#05171d50');c.fillStyle=gradient;c.fillRect(0,0,rect.width,rect.height);}
export function portrait(){return `<svg viewBox="0 0 180 200" role="img" aria-label="Anderson, o ladrão, de gorro e jaqueta"><rect width="180" height="200" rx="8" fill="#314747"/><path d="M21 200q0-69 69-69t69 69" fill="#b18148"/><path d="m65 137 25 47 25-47" fill="#213842"/><path d="M69 140q21 19 42 0v-35H69Z" fill="#bd976e"/><ellipse cx="90" cy="83" rx="37" ry="48" fill="#c8a47c"/><path d="M49 76q-2-55 40-55t42 55" fill="#dfb574"/><path d="M49 65h83v21H49Z" fill="#a47c49"/><path d="M59 84h23m17 0h22" stroke="#263a3d" stroke-width="5"/><path d="m90 89-6 17 13 0" fill="none" stroke="#9b7454" stroke-width="3"/><path d="M75 118q16 8 31-1" fill="none" stroke="#634b3a" stroke-width="3"/><path d="M43 174v26m94-26v26" stroke="#745a38" stroke-width="4"/></svg>`;}
